import type {
  ProfileProvider,
  ProfileReference,
  ProfileRuntime,
} from '../../types/design-profile';
import type { ProfileRecords } from '../../storage/profiles/ProfileRecords';
import type { ProfileMedia } from './ProfileMedia';
import type { ProfileAgent } from './ProfileAgent';
import type { ProfileOperation, TelemetryService } from '../TelemetryService';
import { reportedProfileUsage } from './modelContract';
import {
  fitsAnalysisBatch,
  prepareAnalysisBatch,
  analysisDescription,
  analysisUsage,
  type AnalysisInput,
} from './analysisBatch';
import { errorMessage } from '../../utils/errorMessage';
import { failureReasonCode } from '../../utils/failureReason';
import { saveProvisionalObservation } from './profileEvidence';

interface ProfileAnalysisOptions {
  records: ProfileRecords;
  media: ProfileMedia;
  agent: Pick<ProfileAgent, 'run'>;
  isCurrentAccount: () => boolean;
  batchSize?: 1 | 2 | 4;
  telemetry?: Pick<TelemetryService, 'trackProfileOperation'>;
}

interface AnalysisJob {
  jobId: string;
  runtime: ProfileRuntime;
  signal: AbortSignal;
  provider: ProfileProvider;
}

interface AnalysisOutcome {
  job: AnalysisJob;
  references: ProfileReference[];
  outcome: 'completed' | 'failed';
  startedAt: number;
  error?: unknown;
}

const analysisMediaKind = (
  references: ProfileReference[],
): ProfileOperation['mediaKind'] => {
  const kinds = new Set(
    references.flatMap((reference) =>
      reference.media.length
        ? reference.media.map((media) => media.representation)
        : ['text' as const],
    ),
  );
  if (kinds.size > 1) return 'mixed';
  return [...kinds][0] ?? 'text';
};

export class ProfileAnalysis {
  constructor(private readonly options: ProfileAnalysisOptions) {}

  async run({
    jobId,
    signal,
  }: {
    jobId: string;
    signal: AbortSignal;
  }): Promise<void> {
    const { records, media } = this.options;
    const job = records.jobs().find((item) => item.id === jobId);
    if (!job || job.state !== 'pending') return;
    const input = {
      jobId,
      runtime: job.runtime,
      signal,
      provider: records.source(job.sourceId).provider,
    };
    let batch: AnalysisInput[] = [];
    for (const reference of records.references(job.sourceId)) {
      if (!this.isPending(input)) return;
      const observation = records.observation(reference.id);
      if (observation && observation.evidence !== 'provisional') continue;
      if (reference.unsupportedReason) {
        saveProvisionalObservation(records, reference);
        continue;
      }
      if (reference.media.length < (reference.remoteImages?.length ?? 0))
        continue;
      let startedAt = Date.now();
      try {
        if (!fitsAnalysisBatch([reference]))
          throw new Error(
            'Reference exceeds the analysis budget; split it into smaller references',
          );
        if (
          batch.length >= (this.options.batchSize ?? 4) ||
          !fitsAnalysisBatch([
            ...batch.map((item) => item.reference),
            reference,
          ])
        ) {
          await this.analyze({ ...input, batch });
          batch = [];
          if (!this.isPending(input)) return;
          startedAt = Date.now();
        }
        const images = await Promise.all(
          reference.media.map((image) => media.resolve(image)),
        );
        batch.push({ reference, images });
      } catch (error) {
        if (!this.isPending(input)) return;
        this.fail({ jobId, reference, error });
        this.track({
          job: input,
          references: [reference],
          outcome: 'failed',
          startedAt,
          error,
        });
      }
    }
    if (batch.length && this.isPending(input))
      await this.analyze({ ...input, batch });
  }

  private isPending({
    jobId,
    signal,
  }: Pick<AnalysisJob, 'jobId' | 'signal'>): boolean {
    signal.throwIfAborted();
    if (!this.options.isCurrentAccount())
      throw new Error(
        'Profile analysis paused because the active account changed',
      );
    return (
      this.options.records.jobs().find((item) => item.id === jobId)?.state ===
      'pending'
    );
  }

  private async analyze(
    input: AnalysisJob & { batch: AnalysisInput[] },
  ): Promise<void> {
    if (!this.isPending(input)) return;
    const { batch, runtime, signal, jobId } = input;
    const { agent, records } = this.options;
    const startedAt = Date.now();
    let result: Awaited<ReturnType<ProfileAgent['run']>>;
    try {
      result = await agent.run({
        runtime,
        signal,
        ...prepareAnalysisBatch(batch),
      });
    } catch (error) {
      if (!this.isPending(input)) return;
      for (const { reference } of batch) this.fail({ jobId, reference, error });
      this.track({
        job: input,
        references: batch.map((item) => item.reference),
        outcome: 'failed',
        startedAt,
        error,
      });
      return;
    }
    const analyzed: ProfileReference[] = [];
    const failed: ProfileReference[] = [];
    let failure: unknown;
    for (const { reference, images } of batch) {
      if (!this.isPending(input)) return;
      try {
        if (images.some((image) => !result.inspectedImages.includes(image)))
          throw new Error(
            'The selected agent did not inspect the supplied images',
          );
        const description = analysisDescription({
          value: result.value,
          referenceId: reference.id,
          count: batch.length,
        });
        records.saveObservation({
          referenceId: reference.id,
          revision: reference.revision,
          description,
          runtime,
          evidence: 'observation',
          usage: analysisUsage(
            reportedProfileUsage(result.usage),
            batch.length,
          ),
        });
        records.clearFailure(reference.id, 'analysis');
        analyzed.push(reference);
      } catch (error) {
        this.fail({ jobId, reference, error });
        failed.push(reference);
        failure ??= error;
      }
    }
    if (analyzed.length)
      this.track({
        job: input,
        references: analyzed,
        outcome: 'completed',
        startedAt,
      });
    if (failed.length)
      this.track({
        job: input,
        references: failed,
        outcome: 'failed',
        startedAt,
        error: failure,
      });
  }

  private track({
    job,
    references,
    outcome,
    startedAt,
    error,
  }: AnalysisOutcome): void {
    this.options.telemetry?.trackProfileOperation({
      stage: 'analysis',
      operation: 'analysis',
      outcome,
      durationMs: Date.now() - startedAt,
      referenceCount: references.length,
      jobId: job.jobId,
      provider: job.provider,
      mediaKind: analysisMediaKind(references),
      error,
    });
  }

  private fail({
    jobId,
    reference,
    error,
  }: {
    jobId: string;
    reference: ProfileReference;
    error: unknown;
  }): void {
    this.options.records.saveFailure({
      jobId,
      referenceId: reference.id,
      revision: reference.revision,
      stage: 'analysis',
      error: errorMessage(error, 'Reference analysis failed'),
      reasonCode: failureReasonCode(error),
    });
    saveProvisionalObservation(this.options.records, reference);
  }
}
